diff --git a/src/i18n/language.js b/src/i18n/language.js
new file mode 100644
index 0000000..38c9811
--- /dev/null
+++ b/src/i18n/language.js
@@ -0,0 +1,25 @@
+import { LANGUAGES } from "./messages.js";
+
+/** Chooses the highest-quality supported request language, or the configured fallback. */
+export function requestLanguage(headers, fallback) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return fallback;
+  let language = fallback;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const [range, ...parameters] = entry.trim().split(";");
+    if (!/^[a-z]{2}(?:-[a-z0-9]{1,8})*$/i.test(range)) continue;
+    const candidate = range.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(candidate)) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(.*)$/i.exec(parameter.trim());
+      if (match) quality = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(match[1]) ? Number(match[1]) : 0;
+    }
+    if (quality > bestQuality) {
+      language = candidate;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
